def _path_to_elements(path, root_element=DEFAULT_FIRST_ELEMENT):
    elements = []
    if path == 'root':
        return [root_element]
    path = path.replace('[', '.').replace(']', '')
    parts = path.split('.')
    if parts[0] == 'root':
        parts = parts[1:]
    for part in parts:
        if part:
            _add_to_elements(elements, part, '.')
    return elements


def parse_path(path, root_element=DEFAULT_FIRST_ELEMENT, include_actions=False
    ):
    elements = _path_to_elements(path, root_element)
    if not include_actions:
        return [elem for elem, action in elements]
    return [{'element': elem, 'action': action} for elem, action in elements]


def stringify_path(path, root_element=DEFAULT_FIRST_ELEMENT, quote_str="'{}'"):
    if not path:
        return 'root'
    if isinstance(path, str):
        return path
    if not isinstance(path, list):
        path = list(path)
    result = 'root'
    for elem in path:
        if isinstance(elem, str):
            if '[' in elem or ']' in elem or '.' in elem:
                result += f"['{elem}']"
            else:
                result += f".{elem}"
        elif isinstance(elem, int):
            result += f"[{elem}]"
        else:
            result += f"[{elem}]"
    return result
